"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["85164"],{97096(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.idempotency.body_mismatch","status":422,"titulo":"Mesma Idempotency-Key reusada com body diferente"},"descricao":{"codigo":"uniplus.idempotency.body_mismatch","requisitos":[],"oQueAconteceu":["A `Idempotency-Key` informada j\xe1 foi usada, dentro do prazo de validade da\\nentrada em cache, mas com um **corpo de requisi\xe7\xe3o diferente** do desta\\nchamada.","Durante o prazo de validade, reenviar a mesma chave e o mesmo corpo para a mesma opera\xe7\xe3o devolve a resposta original, sem repetir seus efeitos. A mesma chave com corpo diferente \xe9 recusada. A compara\xe7\xe3o considera todo o conte\xfado: corpos diferentes s\xe3o recusados mesmo quando a diferen\xe7a n\xe3o altera o resultado da opera\xe7\xe3o."],"comoResolver":["Se a inten\xe7\xe3o era reenviar a mesma opera\xe7\xe3o (por exemplo, ap\xf3s timeout de\\nrede), reenvie com o corpo id\xeantico ao da tentativa original. Se a inten\xe7\xe3o\\n\xe9 uma opera\xe7\xe3o diferente, gere uma nova `Idempotency-Key` \u2014 reaproveitar o\\nmesmo valor entre chamadas logicamente distintas \xe9 o uso incorreto que esta\\ncausa existe para recusar."],"ondeAparece":["Opera\xe7\xf5es que exigem `Idempotency-Key`"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Idempot\xeancia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);